  // Channels — assignment notices
  Connect: ["Conectar", "Verbinden", "Bağla"],
  "Create an AI Employee": ["Crear un empleado de IA", "KI-Mitarbeiter erstellen", "Yapay zekâ çalışanı oluştur"],
  "Create an employee first — it takes a minute.": ["Primero crea un empleado: se tarda un minuto.", "Erstellen Sie zuerst einen Mitarbeiter – das dauert eine Minute.", "Önce bir çalışan oluşturun; bir dakika sürer."],
  "No AI Employee is assigned to": ["Ningún empleado de IA está asignado a", "Kein KI-Mitarbeiter ist zugewiesen für", "Şuna atanmış bir yapay zekâ çalışanı yok:"],

  // Conversation detail
  "No contact record linked to this conversation yet.": ["Aún no hay ninguna ficha de contacto vinculada a esta conversación.", "Dieser Unterhaltung ist noch kein Kontakt zugeordnet.", "Bu konuşmaya henüz bir müşteri kaydı bağlanmadı."],
  "Your browser can't play this recording.": ["Tu navegador no puede reproducir esta grabación.", "Ihr Browser kann diese Aufnahme nicht abspielen.", "Tarayıcınız bu kaydı oynatamıyor."],
  "No message history for this conversation.": ["No hay historial de mensajes para esta conversación.", "Für diese Unterhaltung gibt es keinen Nachrichtenverlauf.", "Bu konuşmaya ait mesaj geçmişi yok."],
  "Takeover isn't available on this environment yet — the handling migration hasn't been applied. The conversation itself is unaffected.": ["Aún no puedes tomar el control en este entorno: falta aplicar la migración de gestión. La conversación en sí no se ve afectada.", "Die Übernahme ist in dieser Umgebung noch nicht verfügbar – die Handling-Migration wurde nicht angewendet. Die Unterhaltung selbst ist davon nicht betroffen.", "Bu ortamda devralma henüz kullanılamıyor; ilgili veritabanı güncellemesi uygulanmamış. Konuşmanın kendisi bundan etkilenmez."],
  "This customer has opted out of automated handling. Their messages are still stored and shown to your team — they are simply never processed automatically.": ["Este cliente ha rechazado la gestión automática. Sus mensajes se siguen guardando y mostrando a tu equipo; simplemente nunca se procesan de forma automática.", "Dieser Kunde hat der automatischen Bearbeitung widersprochen. Seine Nachrichten werden weiterhin gespeichert und Ihrem Team angezeigt – sie werden nur nie automatisch bearbeitet.", "Bu müşteri otomatik yanıtlanmayı reddetti. Mesajları yine saklanır ve ekibinize gösterilir; yalnızca otomatik olarak işlenmez."],

  // Saved views
  "Could not change that view.": ["No se pudo cambiar esa vista.", "Diese Ansicht konnte nicht geändert werden.", "Bu görünüm değiştirilemedi."],
