  "An unexpected error occurred. Please try again.": ["Se ha producido un error inesperado. Inténtalo de nuevo.", "Ein unerwarteter Fehler ist aufgetreten. Bitte versuchen Sie es erneut.", "Beklenmeyen bir hata oluştu. Lütfen tekrar deneyin."],
  "Invalid response from server. Please try again.": ["Respuesta no válida del servidor. Inténtalo de nuevo.", "Ungültige Antwort vom Server. Bitte versuchen Sie es erneut.", "Sunucudan geçersiz yanıt geldi. Lütfen tekrar deneyin."],
  "Failed to delete phone line. Please try again.": ["No se ha podido eliminar la línea telefónica. Inténtalo de nuevo.", "Die Telefonleitung konnte nicht gelöscht werden. Bitte versuchen Sie es erneut.", "Telefon hattı silinemedi. Lütfen tekrar deneyin."],
  "Error ID:": ["ID de error:", "Fehler-ID:", "Hata kimliği:"],
  "No organization found. Please contact support.": ["No se ha encontrado ninguna organización. Contacta con soporte.", "Keine Organisation gefunden. Bitte kontaktieren Sie den Support.", "Kuruluş bulunamadı. Lütfen destek ekibiyle iletişime geçin."],
  "No phone lines yet": ["Aún no hay líneas telefónicas", "Noch keine Telefonleitungen", "Henüz telefon hattı yok"],
  "Add a phone number to start receiving calls.": ["Añade un número de teléfono para empezar a recibir llamadas.", "Fügen Sie eine Telefonnummer hinzu, um Anrufe zu empfangen.", "Arama almaya başlamak için bir telefon numarası ekleyin."],
  "Choose a plan": ["Elegir un plan", "Plan wählen", "Plan seçin"],
  "Choose a plan to activate phone lines": ["Elige un plan para activar las líneas telefónicas", "Wählen Sie einen Plan, um Telefonleitungen zu aktivieren", "Telefon hatlarını etkinleştirmek için bir plan seçin"],
  "Preview mode is read-only. Upgrade to add phone numbers and take live calls.": ["El modo de vista previa es de solo lectura. Mejora tu plan para añadir números y recibir llamadas reales.", "Der Vorschaumodus ist schreibgeschützt. Führen Sie ein Upgrade durch, um Nummern hinzuzufügen und Anrufe entgegenzunehmen.", "Önizleme modu salt okunurdur. Numara eklemek ve gerçek arama almak için planınızı yükseltin."],
  "Upgrade to activate this feature": ["Mejora tu plan para activar esta función", "Upgraden Sie, um diese Funktion zu aktivieren", "Bu özelliği etkinleştirmek için planınızı yükseltin"],
  "View line details": ["Ver detalles de la línea", "Leitungsdetails ansehen", "Hat ayrıntılarını gör"],
  "Delete line": ["Eliminar línea", "Leitung löschen", "Hattı sil"],
