const MESSAGE_TREES: Record<Locale, unknown> = { en, es, de, tr };
const cache = new Map<Locale, Readonly<Record<string, string>>>();

/** Collect already-reviewed marketing translations when the English value is reused in the app. */
function collectParallelStrings(
  source: unknown,
  target: unknown,
  output: Record<string, string>,
) {
  if (typeof source === "string" && typeof target === "string") {
    if (source && target && source !== target) output[source] = target;
    return;
  }
  if (Array.isArray(source) && Array.isArray(target)) {
    const length = Math.min(source.length, target.length);
    for (let index = 0; index < length; index += 1) {
      collectParallelStrings(source[index], target[index], output);
    }
    return;
  }
  if (!source || !target || typeof source !== "object" || typeof target !== "object") return;

  const sourceRecord = source as Record<string, unknown>;
  const targetRecord = target as Record<string, unknown>;
  for (const key of Object.keys(sourceRecord)) {
    if (key in targetRecord) collectParallelStrings(sourceRecord[key], targetRecord[key], output);
  }
}

export function getDashboardDictionary(locale: Locale): Readonly<Record<string, string>> {
  if (locale === "en") return {};
  const existing = cache.get(locale);
  if (existing) return existing;

  const output: Record<string, string> = {};
  collectParallelStrings(MESSAGE_TREES.en, MESSAGE_TREES[locale], output);

  const tupleIndex = locale === "es" ? 0 : locale === "de" ? 1 : 2;
  for (const [english, translations] of Object.entries(DASHBOARD_COPY)) {
    output[english] = translations[tupleIndex];
  }

  const frozen = Object.freeze(output);
  cache.set(locale, frozen);
  return frozen;
}
